import{_ as e,o,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Q and A Panel","description":"","frontmatter":{"title":"Q and A Panel","date":"2025-06-23T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","文档改进","版本支持"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Q_and_A_Panel.md","filePath":"posts/2025/Q_and_A_Panel.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Q_and_A_Panel.md"};function l(n,a,s,d,h,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<p>会议纪要：</p><p>本次Ceph社区会议主要围绕Ceph分布式存储系统的最新进展、性能优化、文档改进、版本支持策略等方面进行了深入讨论。以下是对会议内容的详细总结：</p><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次会议邀请了多位核心开发者参与，包括Bill、Jose等，他们分享了技术更新，并回答了社区成员的提问。</p><h2 id="主要讨论议题" tabindex="-1">主要讨论议题 <a class="header-anchor" href="#主要讨论议题" aria-label="Permalink to &quot;主要讨论议题&quot;">​</a></h2><h3 id="_1-性能优化与crimson-ec整合" tabindex="-1">1. 性能优化与Crimson/EC整合 <a class="header-anchor" href="#_1-性能优化与crimson-ec整合" aria-label="Permalink to &quot;1. 性能优化与Crimson/EC整合&quot;">​</a></h3><ul><li><strong>Crimson与EC的协同开发</strong>：Crimson将直接使用Fast EC路径，避免重复开发，并将在未来全面支持EC。</li><li><strong>NVMe与RBD的优化</strong>：计划优化SPDK与RBD的集成，避免重复计算CRC，并探索librados线程与SPDK reactors的协同运行。</li></ul><h3 id="_2-文件系统与存储协议" tabindex="-1">2. 文件系统与存储协议 <a class="header-anchor" href="#_2-文件系统与存储协议" aria-label="Permalink to &quot;2. 文件系统与存储协议&quot;">​</a></h3><ul><li><strong>SMB/NFS的并发访问问题</strong>：目前SMB和NFS的锁机制不互通，导致跨协议访问冲突，社区正在讨论解决方案。</li><li><strong>CephFS新VFS模块性能测试</strong>：团队正在虚拟机和物理机环境进行基准测试，后续将公布性能对比数据。</li></ul><h3 id="_3-文档与用户体验改进" tabindex="-1">3. 文档与用户体验改进 <a class="header-anchor" href="#_3-文档与用户体验改进" aria-label="Permalink to &quot;3. 文档与用户体验改进&quot;">​</a></h3><ul><li><strong>文档不足的问题</strong>：社区成员反馈Ceph文档存在版本差异，BlueStore的性能计数器缺乏解释，团队鼓励用户通过GitHub Issue或Slack提交具体问题。</li><li><strong>mclock调度器的优化</strong>：<code>mclock</code>旨在简化参数配置，但初期实现存在硬编码问题，未来将提供更多灵活性。</li></ul><h3 id="_4-ceph-dashboard与存储浏览器" tabindex="-1">4. Ceph Dashboard与存储浏览器 <a class="header-anchor" href="#_4-ceph-dashboard与存储浏览器" aria-label="Permalink to &quot;4. Ceph Dashboard与存储浏览器&quot;">​</a></h3><ul><li><strong>存储浏览器功能开发</strong>：计划在Ceph Dashboard中集成对象存储浏览器，支持上传/删除对象。</li></ul><h3 id="_5-版本支持策略" tabindex="-1">5. 版本支持策略 <a class="header-anchor" href="#_5-版本支持策略" aria-label="Permalink to &quot;5. 版本支持策略&quot;">​</a></h3><ul><li><strong>长期支持（LTS）版本的缺失</strong>：Ceph目前仅支持N-2版本，版本重叠期较短，未来目标：恢复春季/夏季发布周期。</li></ul><h2 id="关键决策与行动计划" tabindex="-1">关键决策与行动计划 <a class="header-anchor" href="#关键决策与行动计划" aria-label="Permalink to &quot;关键决策与行动计划&quot;">​</a></h2><ol><li><strong>Crimson与EC的整合</strong>：确保Fast EC路径在Crimson中稳定运行，并同步性能优化。</li><li><strong>NVMe/RBD优化</strong>：测试SPDK与RBD的CRC计算优化方案。</li><li><strong>文档改进</strong>：针对<code>mclock</code>、BlueStore计数器等补充文档。</li><li><strong>Ceph Dashboard存储浏览器</strong>：推进自主开发的Angular集成方案。</li><li><strong>版本发布节奏调整</strong>：缩短开发周期，确保&quot;Umbrella&quot;版本按时发布。</li></ol><h2 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h2><ul><li>社区成员可通过GitHub/Slack提交具体问题。</li><li>性能测试结果将在完成后公开。</li><li>下一次会议将讨论SMB/NFS锁机制的可行性方案。</li></ul><h2 id="关键词保留" tabindex="-1">关键词保留 <a class="header-anchor" href="#关键词保留" aria-label="Permalink to &quot;关键词保留&quot;">​</a></h2><p>Ceph、CRUSH、Crimson、EC、RBD、SPDK、BlueStore、mclock、PG、OSD、librados、libcephfs、cephfs、rbd、radosgw、RGW、RESTful API、authentication、authorization、encryption、erasure coding、replication、snapshots、clones、thin provisioning、iSCSI、Fibre Channel、NFS、CIFS、POSIX、monitoring、dashboard、management、orchestration、automation、integration、containerization、Kubernetes、Docker、virtualization、cloud computing、AWS、Azure、Google Cloud、hybrid cloud、multi-cloud、storage cluster、node、disk、SSD、HDD、JBOD、SAN、NAS、network、topology、failure domain、recovery、resilience、load balancing、caching、compression、deduplication、tiering、performance tuning、benchmarking、testing、validation</p>',21)])])}const g=e(i,[["render",l]]);export{p as __pageData,g as default};
